// @ts-ignore .open-next/worker.js is generated by the OpenNext build.
import { default as handler } from "./.open-next/worker.js";

type ScheduledExecutionContext = {
  waitUntil(promise: Promise<unknown>): void;
};

export default {
  fetch: handler.fetch,

  async scheduled(
    _controller: { cron: string; scheduledTime: number },
    _env: unknown,
    ctx: ScheduledExecutionContext,
  ) {
    const task = import("./src/lib/engine/runner")
      .then(({ runScheduledTasks }) => runScheduledTasks())
      .catch((error) => {
        console.error("[scheduled-engine]", error instanceof Error ? error.message : error);
      });

    ctx.waitUntil(task);
  },
};
